    public static void testTheProbeAsksInTwoRoundsAndThenWritesEvidence() {
        emon.Port.Src s = emon.Port.srcOfBlob(emon.Testport.textBlob("0123456789abcdef"));
        emon.Port.Cells an = emon.Port.newCells();
        emon.Port.Cells rq = emon.Port.newCells();
        emon.Port.Cells et = emon.Port.newCells();
        StringBuilder t = emon.Testport.newText();
        emon.Testport.assertEq(ptUnit(s, an, rq, et, t), 1, "round 0 asks");
        emon.Testport.assertEq(Plan.recCount(rq), 2, "for two things");
        emon.Testport.assertEq(Plan.recCheck(rq, 1, 3), 0, "well formed");
        emon.Testport.assertEq(Plan.recId(rq, 0), 1, "the render is id 1");
        emon.Testport.assertEq(Plan.recKind(rq, 0), 1, "a render");
        int second = Plan.recNext(rq, 0);
        emon.Testport.assertEq(Plan.recKind(rq, second), 2, "and a decode");
        Plan.anRender(an, 1, 64, 48, 1, 300);
        Plan.anDecode(an, 2, 32, 16, 3, 7200, 0, 1);
        emon.Port.cellsDrop(rq, 0);
        emon.Testport.assertEq(ptUnit(s, an, rq, et, t), 1, "round 1 asks");
        emon.Testport.assertEq(Plan.recCount(rq), 2, "for two OCRs");
        emon.Testport.assertEq(Plan.recId(rq, 0), 3, "id 3");
        emon.Testport.assertEq(Plan.rqArg(rq, 0, 0), 1, "of the render's bitmap");
        int second4 = Plan.recNext(rq, 0);
        emon.Testport.assertEq(Plan.recId(rq, second4), 4, "id 4");
        emon.Testport.assertEq(Plan.rqArg(rq, second4, 0), 2, "of the decode's bitmap");
        int o3 = Plan.anOcr(an, 3);
        int w = Plan.anOcrWord(an, o3, 6, 3, 40, 9, 911, 0, 0);
        Plan.anOcrCp(an, w, 72);
        Plan.anOcrCp(an, w, 105);
        Plan.anOcrEnd(an, o3);
        Plan.anFail(an, 3, 4, 1);
        emon.Port.cellsDrop(rq, 0);
        emon.Testport.assertEq(ptUnit(s, an, rq, et, t), 0, "round 2 is done");
        emon.Testport.assertEq(emon.Port.cellsLen(rq), 0, "and asks for nothing");
    }
